{
  "schemaVersion": "0.2",
  "slug": "typography",
  "name": "Typography",
  "status": "experimental",
  "purpose": "Presents text using the design-system type scale across breakpoints.",
  "scenarios": [
    "Render a page heading that scales with viewport width",
    "Display body copy in a readable measure",
    "Show secondary metadata with a caption style"
  ],
  "props": {
    "variant": {
      "type": "enum",
      "required": false,
      "description": "Type scale level.",
      "values": [
        "heading-1",
        "heading-2",
        "body",
        "caption"
      ],
      "default": "body"
    },
    "as": {
      "type": "enum",
      "required": false,
      "description": "Semantic element to render; defaults from the variant if omitted.",
      "values": [
        "h1",
        "h2",
        "h3",
        "p",
        "span",
        "div"
      ]
    }
  },
  "variants": [
    {
      "name": "variant",
      "values": [
        "heading-1",
        "heading-2",
        "body",
        "caption"
      ],
      "default": "body",
      "description": "Type scale level that maps to size and weight."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Text rendered at the chosen scale."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "dialog",
      "alert",
      "page"
    ],
    "allowedChildren": [
      "text",
      "icon"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use heading variants only for visual size; keep the document outline semantic.",
    "Do not hardcode colors; use token-provided foreground colors."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Text is not focusable.",
    "labeling": "Headings create the document outline; other text is labelled by context.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Font sizes scale with the viewport using clamp() so text stays readable on compact screens.",
    "breakpoints": {
      "compact": "Heading sizes are capped at the lower clamp bound to avoid overflow.",
      "medium": "Heading sizes grow with available space.",
      "large": "Heading sizes reach their upper bound."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "typography",
    "states": [
      "heading-1",
      "heading-2",
      "body",
      "caption"
    ],
    "intents": [
      "style-text"
    ]
  }
}

.cu-typography {
  margin: 0;
  color: var(--cu-color-fg-default);
}

.cu-typography--heading-1 {
  font-size: var(--cu-typography-size-heading-1);
  line-height: var(--cu-typography-line-height-tight);
  font-weight: var(--cu-typography-weight-semibold, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.022em);
}

.cu-typography--heading-2 {
  font-size: var(--cu-typography-size-heading-2);
  line-height: var(--cu-typography-line-height-snug);
  font-weight: var(--cu-typography-weight-semibold, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.022em);
}

.cu-typography--body {
  font-size: var(--cu-typography-size-body, 1rem);
  line-height: var(--cu-typography-line-height-body, 1.6);
  letter-spacing: var(--cu-typography-tracking-body, 0em);
}

.cu-typography--caption {
  font-size: var(--cu-typography-size-caption, 0.875rem);
  line-height: var(--cu-typography-line-height-snug, 1.25);
  color: var(--cu-color-fg-muted, var(--cu-color-fg-default));
}

import type { ReactNode } from 'react'
import './styles.css'

export type TypographyVariant = 'heading-1' | 'heading-2' | 'body' | 'caption'

export interface TypographyProps {
  variant?: TypographyVariant
  /** Semantic element to render; defaults from the variant if omitted. */
  as?: 'h1' | 'h2' | 'h3' | 'p' | 'span' | 'div'
  children: ReactNode
  className?: string
}

const defaultElement: Record<TypographyVariant, 'h1' | 'h2' | 'p' | 'span'> = {
  'heading-1': 'h1',
  'heading-2': 'h2',
  body: 'p',
  caption: 'span',
}

export function Typography({ variant = 'body', as, children, className }: TypographyProps) {
  const Element = as ?? defaultElement[variant]
  const classes = ['cu-typography', `cu-typography--${variant}`, className].filter(Boolean).join(' ')

  return (
    <Element className={classes} data-ai-role="typography" data-ai-intent="style-text" data-ai-state={variant} data-variant={variant}>
      {children}
    </Element>
  )
}
